<template>
  <div
    class="min-h-screen flex items-center justify-center bg-gradient-to-br from-slate-900 via-slate-800 to-petroleum px-4 sm:px-6 lg:px-8 relative overflow-hidden">

    <div class="w-full  flex items-center justify-center lg:justify-between relative z-10">

      <div class="hidden lg:flex lg:w-1/2 justify-center items-center pr-8">
        <div class="relative w-full h-full">
          <div
            class="absolute inset-0 bg-gradient-to-r from-color2/20 via-color3/30 to-color1/20 rounded-3xl transform rotate-3 blur-2xl scale-110">
          </div>
          <img src="@/assets/auth/login5.jpeg" alt="SIMTRA - Hombre con casco verde"
            class="relative w-full h-full object-cover rounded-3xl drop-shadow-1xl transform hover:scale-105 transition-transform duration-700 ease-out" />
        </div>
      </div>


      <div class="w-full lg:w-1/2 max-w-md relative">
        <div class="text-center mb-8">

          <router-link to="/start"
            class="flex items-center justify-center space-x-1 text-3xl font-bold tracking-wider mb-3 cursor-pointer hover:opacity-80 transition-opacity">
            <span class="text-color1">S</span>
            <span class="text-accent-success">I</span>
            <span class="text-color2">M</span>
            <span class="text-color3">T</span>
            <span class="text-color4">R</span>
            <span class="text-accent-primary">A</span>
          </router-link>


          <p class="text-slate-300 text-sm">Sistema Inteligente de Monitoreo de Transformadores en Tiempo Real</p>
        </div>

        <div
          class="bg-white/5 backdrop-blur-2xl rounded-2xl shadow-2xl border border-white/10 p-8 hover:bg-white/10 transition-all duration-300">
          <FormLogin @submit="handleLogin" :loading="isLoading" />
          <p v-if="errorMsg" class="mt-3 text-sm text-accent-danger">{{ errorMsg }}</p>
          <div class="mt-6 mb-6">
            <div class="relative">
              <div class="absolute inset-0 flex items-center">
                <div class="w-full border-t border-color3/20"></div>
              </div>
            </div>
          </div>


          <div class="mt-6 text-center space-y-2">
            <a class="text-color4/80 hover:text-color3 text-sm transition-colors duration-200 font-medium"
              @click="showSupport = true">
              ¿Olvidaste tu contraseña?
            </a>


            <div class="text-slate-400 text-xs">
              ¿No tienes cuenta?
              <a class="text-color3 hover:text-color2 font-medium transition-colors duration-200 "
                @click="showQuoteForm = true">
                Solicitar acceso
              </a>
            </div>
          </div>
        </div>


        <div class="mt-8 text-center">
          <div
            class="flex items-center justify-center space-x-1 text-sm font-bold tracking-wider mb-2 opacity-60 cursor-pointer"
            @click="$router.push('/start')">
            <span class="text-color1">S</span>
            <span class="text-accent-success">I</span>
            <span class="text-color2">M</span>
            <span class="text-color3">T</span>
            <span class="text-color4">R</span>
            <span class="text-accent-primary">A</span>
          </div>


          <p class="text-slate-500 text-xs">SIMTRA - D&A Intelligent Solutions © 2025 Todos los derechos reservados</p>
          <div class="flex justify-center items-center mt-3 space-x-4 text-slate-500">
            <a href="#" class="hover:text-color4 transition-colors text-xs">Política de Privacidad</a>
            <span class="w-1 h-1 bg-color3/50 rounded-full"></span>
            <a href="#" class="hover:text-color4 transition-colors text-xs">Términos de Uso</a>
          </div>
        </div>
      </div>
    </div>

  </div>

  <QuoteForm v-model="showQuoteForm" class="backdrop-blur-md" />

  <v-dialog v-model="showSupport" max-width="1050px" class="backdrop-blur-md">
    <FormSupport @close="closeSupportModal" @success="handleProfileSuccess" />
  </v-dialog>
</template>

<script setup>
import { ref, getCurrentInstance } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import FormLogin from '../components/FormLogin.vue'
import { login as apiLogin } from '../services/authService'
import { useAuthStore } from '@/features/auth/stores/authStore'
import QuoteForm from '@/components/ui/forms/QuotationForm.vue'
import FormSupport from '@/features/support/components/FormSupport.vue'
const router = useRouter()
const route = useRoute()
const auth = useAuthStore()
const isLoading = ref(false)
const errorMsg = ref('')
const bus = getCurrentInstance()?.appContext.config.globalProperties.$bus
const showQuoteForm = ref(false)
const showSupport = ref(false)
const handleLogin = async (credentials) => {
  isLoading.value = true
  errorMsg.value = ''
  try {
    const { access_token, user } = await apiLogin(credentials)

    auth.setSession({ access_token, user })

   // bus?.emit?.('success', 'Sesión iniciada correctamente')
    router.push(route.query.redirect || '/')
  } catch (e) {
    errorMsg.value = e?.response?.data?.message || 'Credenciales inválidas'
    bus?.emit?.('error', errorMsg.value)
  } finally {
    isLoading.value = false
  }
}


function closeSupportModal() {
  showSupport.value = false
}

function handleProfileSuccess() {
  showSupport.value = false
  bus?.emit?.('success', 'Solicitud enviada correctamente')
}
</script>
